{
  "up": "Select molecule_chembl_id AS compound_chembl_id, compound_structures.canonical_smiles AS canonical_smiles From molecule_dictionary Join activities On molecule_dictionary.molregno = activities.molregno Join assays On activities.assay_id = assays.assay_id Join target_dictionary On assays.tid = target_dictionary.tid Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where target_dictionary.pref_name = 'Adenosine A3 receptor' And assays.assay_organism = 'Homo sapiens' And assays.assay_type = 'B' And activities.standard_type = 'IC50' And activities.standard_relation = '=' And activities.standard_value IS NOT NULL And activities.standard_value > 0 Order By molecule_chembl_id Asc Limit 100"
}
